    def tokenize(self, value: bytes) -> Token: ...
    @overload
    def tokenize(self, value: int) -> Token: ...
    @overload
    def tokenize(self, value: float) -> Token: ...
    @overload
    def tokenize(self, value: datetime) -> Token: ...
    @overload
    def tokenize(self, value: None) -> Token: ...
