final class TokenRegistry[T] {
  private val registry = mutable.Map.empty[String, TokenContainer[T]]
  private val handlers = mutable.ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.update(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): Vector[Option[Token]] = {
    registry.get(key) match {
      case None => Vector.empty
      case Some(container) =>
        val result = Vector.newBuilder[Option[Token]]
        container.getAll.foreach { item =>
          var handled: Option[Token] = None
          val iterator = handlers.iterator
          while (iterator.hasNext && handled.isEmpty) {
            handled = iterator.next()(item)
          }
          result += handled
        }
        result.result()
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation
// ============================================================================

class TokenFunctor[A](private val value: A) {
  def map[B](func: A => B): TokenFunctor[B] = new TokenFunctor(func(value))
  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] = func(value)
  def getOrElse(default: A): A = if (value == null) default else value
  def get: A = value
}

final class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] = new TokenMonad(funcWrapped.get.apply(get))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  private val printer: Printer = if (pretty) Printer.spaces2 else Printer.noSpaces

  def tokenize(value: Json): Token = {
    val jsonStr = printer.print(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toVector.filter(_.nonEmpty)

    def step(current: Json, remaining: Vector[String]): Option[Json] = remaining match {
      case Vector() => Some(current)
      case head +: tail =>
        current.asObject.flatMap(_.apply(head)) match {
          case some @ Some(_) => some.flatMap(step(_, tail))
          case None =>
            current.asArray
              .flatMap { array => head.toIntOption.flatMap(idx => array.lift(idx)) }
              .flatMap(step(_, tail))
        }
    }

    step(value, parts).map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}"

  private def stripPunct(word: String): String = {
    val startStripped = word.dropWhile(ch => punctuation.contains(ch))
    startStripped.reverse.dropWhile(ch => punctuation.contains(ch)).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripPunct(word) else word
    val lowered = if (lowercase) stripped.toLowerCase(Locale.ROOT) else stripped

    if (lowered.length < minLength) return None

    val bounded = maxLength match {
      case Some(max) if lowered.length > max => lowered.take(max)
      case _ => lowered
    }

    if (bounded.isEmpty) None else Some(bounded)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList.filter(_.nonEmpty)
    val tokens = List.newBuilder[Token]

    words.zipWithIndex.foreach { case (word, idx) =>
      processToken(word).foreach { processed =>
        tokens += Token(processed, TokenType.STRING, Map("position" -> idx, "original" -> word))
      }
    }

    tokens.result()
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = List.newBuilder[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").toList.filter(_.nonEmpty).foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.result()
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final case class TokenizerBuilder[T](
  normalizers: Vector[String => String] = Vector.empty,
  validators: Vector[T => Boolean] = Vector.empty,
  metadata: Map[String, Any] = Map.empty
) {
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    copy(normalizers = normalizers :+ normalizer)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    copy(validators = validators :+ validator)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] =
    copy(metadata = metadata ++ entries)

  def build(): T => Token = { value =>
    validators.foreach { validator =>
      if (!validator(value)) throw new IllegalArgumentException(s"Validation failed for $value")
    }

    val normalized = normalizers.foldLeft(value.toString) { (acc, normalizer) =>
      normalizer(acc)
    }

    Token(normalized, TokenType.STRING, metadata)
  }
}

